def classify_N(N):
    """
    Determines if N is Type A (A wins) or Type B (B wins) using backward induction.
    Win[n] is True if the player whose turn it is at state n wins.
    """
    if N <= 0:
        return "Invalid N"

    # Win array stores the result for states n = 1 to N-1.
    Win = [False] * (N + 1)

    # Backward induction from N-1 down to 1
    for n in range(N - 1, 0, -1):
        # Check move to n+1
        wins_n_plus_1 = False
        if n + 1 == N:
            wins_n_plus_1 = True
        elif n + 1 < N:
            if not Win[n + 1]:
                wins_n_plus_1 = True

        # Check move to 2n
        wins_2n = False
        if 2 * n == N:
            wins_2n = True
        elif 2 * n < N:
            if not Win[2 * n]:
                wins_2n = True

        Win[n] = wins_n_plus_1 or wins_2n

    if Win[1]:
        return "Type A"
    else:
        return "Type B"

# Find the least N > 400 such that it is Type B
N = 401
while True:
    result = classify_N(N)
    print(f"Checking N={N}: {result}")
    if result == "Type B":
        print(f"\nFound the least N > 400 that is Type B: N = {N}")
        break
    N += 1

